 function addProp(index){const x=-1.5+(index%4)*.8,z=6+Math.floor(index/4)*.8,mesh=B.MeshBuilder.CreateBox('physics-crate-'+index,{size:.58},scene);mesh.position.set(x,forestHeight(x,z)+1.4+(index%3)*.5,z);mesh.material=crateMat;mesh.receiveShadows=true;if(runtime.software)assets.image(bark.diff_low).then(image=>{if(!mesh.isDisposed())mesh.metadata={softwareTexture:{image}};});const body=dynamicBox(runtime,mesh,{mass:2,friction:.75,restitution:.12});props.push({id:'crate-'+index,mesh,body,origin:{x,y:mesh.position.y,z}});graphics.addShadowCaster(mesh);}
