 for(const y of[.6,2.35]){const beam=B.MeshBuilder.CreateBox('gate-door-crossbeam',{width:3.05,height:.14,depth:.19},scene);beam.parent=doorRoot;beam.position.set(0,y,-.1);beam.material=doorMaterial;owned.push(beam);graphics.addShadowCaster(beam);}
