 doorRoot.position.set(0,forestHeight(0,16.8)+model.doorProgress*3.7,16.8);doorCollider.position.set(0,doorRoot.position.y+1.55,16.8);doorCollider.computeWorldMatrix(true);lever.rotation.z=model.doorOpened?-.5:.5;
