  const focus=runtime.camera.target;for(const d of decor){const distance=Math.hypot(d.point.x-focus.x,d.point.z-focus.z),near=distance<settings.distance,detail=d.category==='tree'||d.rank<settings.foliage,high=!!d.high&&distance<14&&settings.preset!=='low';d.root.setEnabled(near&&detail&&!high);d.high?.root.setEnabled(near&&detail&&high);if(d.category==='tree'&&near)for(const root of [d.root,...(d.high?[d.high.root]:[])])for(const n of root.getDescendants())if(n.name.toLowerCase().includes('leav')&&!n.skeleton){n.metadata={...n.metadata,windRest:n.metadata?.windRest||n.rotationQuaternion?.clone()||B.Quaternion.Identity()};n.rotationQuaternion=n.metadata.windRest.multiply(B.Quaternion.FromEulerAngles(0,0,Math.sin(t*.75+d.point.x)*.012));}}
