  while(model.events.length){const e=model.events.shift();if(e.type==='lantern'){const p=LANTERNS[e.id];effects.burst({x:p.x,y:forestHeight(p.x,p.z)+1.6,z:p.z},'#e7ce8c',12);}if(e.type==='push'){const p=props.find(p=>p.id===e.id);if(p){const velocity=p.body.body.getLinearVelocity();if(Math.hypot(velocity.x,velocity.z)<3)p.body.body.applyImpulse(new B.Vector3(e.x,0,e.z),p.mesh.getAbsolutePosition());}}if(['hit','defeat','impact','pulse'].includes(e.type))effects.burst(e.point,e.type==='defeat'?'#edc584':e.type==='hit'?'#e5ad7b':'#a1d5bd',e.type==='defeat'?14:5);onCue(e);}effects.update(dt);
